using Avalonia.Media;

namespace ElectronicJournal.ViewModels;

public sealed record NavigationItem(
    string Title,
    PageViewModelBase Page,
    string Icon = "",
    string Description = "")
{
    public StreamGeometry IconGeometry { get; } = StreamGeometry.Parse(
        string.IsNullOrWhiteSpace(Icon) ? NavigationIcons.Default : Icon);

    public string ShortTitle => string.IsNullOrWhiteSpace(Icon)
        ? Title[..System.Math.Min(2, Title.Length)].ToUpperInvariant()
        : Icon;
}

